import { isAbsolute, join } from "path";
import { readFileSync, statSync } from "fs";
import { ENV } from "@/lib/env";
import logger from "@/lib/logger";
import { sanitizeHostname } from "@/lib/validators";
import { extractHostnameLabel } from "@/lib/network/path-utils";

const PLANNING_CHECK_INTERVAL_MS = 5_000;

const PLANNING_PATH = (() => {
  const configuredPath = ENV.PLANNING_PATH?.trim();
  if (!configuredPath) {
    return join(process.cwd(), "planning", "planning.json");
  }

  const isAbsolutePath = configuredPath.startsWith("\\\\")
    || /^[a-zA-Z]:[\\/]/.test(configuredPath)
    || isAbsolute(configuredPath);
  return isAbsolutePath ? configuredPath : join(process.cwd(), configuredPath);
})();

