type PlanningData = {
  HorairesDefinis?: Record<string, PlanningScheduleValue>;
  Affectations?: Array<{
    Pattern?: unknown;
    Profil?: unknown;
    DomainID?: unknown;
    _S_?: unknown;
  }>;
};

const planningCache: {
  loaded: boolean;
  mtimeMs: number | null;
  lastCheckedAt: number;
  profileByPattern: Map<string, string>;
  maxDeltaByProfile: Map<string, number>;
