  loaded: false,
  mtimeMs: null,
  lastCheckedAt: 0,
  profileByPattern: new Map<string, string>(),
  maxDeltaByProfile: new Map<string, number>(),
};

function normalizePlanningKey(value: string): string {
  return value.trim().toUpperCase();
}

function parseScheduleToMinutes(value: PlanningScheduleValue): number | null {
  if (Array.isArray(value)) {
    const hours = Array.from(new Set(
      value
        .map((item) => Number(item))
        .filter((item) => Number.isInteger(item) && item >= 0 && item <= 23)
    )).sort((a, b) => a - b);

    if (hours.length === 0) return null;
    if (hours.length === 1) return 24 * 60;

    let minGapHours = 24;
    for (let i = 0; i < hours.length; i++) {
      const current = hours[i];
      const next = hours[(i + 1) % hours.length];
      const gap = (next - current + 24) % 24;
      if (gap > 0 && gap < minGapHours) {
        minGapHours = gap;
      }
    }
    return minGapHours * 60;
  }

  if (typeof value === "string") {
    const normalized = value.trim().toUpperCase();
    let match = normalized.match(/^(\d+)\s*MIN(?:UTE)?S?$/);
    if (match) {
      return Number(match[1]);
    }

    match = normalized.match(/^(\d+)\s*H(?:EURE)?S?$/);
    if (match) {
      return Number(match[1]) * 60;
    }
  }

  return null;
}

