3	# ==============================================================================
4	# SYNCHRONISATION PROCÉDURE DÉGRADÉE - MODE CONVERGENCE AVEC .CRED
5	# ==============================================================================
6	 
7	$jsonPath         = "C:\ProcDeg\Config\planning.json"
8	$MaxThreads       = 5
9	$7zPath           = "C:\Program Files\7-Zip\7z.exe"
10	$LogPath          = "C:\ProcDeg\Logs"
11	$TempExtractRoot  = "C:\ProcDeg\Temp"
12	$StateRoot        = "C:\ProcDeg\State"
13	$RunLockPath      = "C:\ProcDeg\Config\run.lock"
14	$GlobalTimeoutSec = 840
15	$SourceMountTimeoutSec = 20
16	$SourceScanTimeoutSec  = 10
17	
18	$LogFileName = "Deploy_$($PID)_$(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss').log"
19	$FullLogPath = Join-Path $LogPath $LogFileName
20	
21	foreach ($path in @($LogPath, $TempExtractRoot, $StateRoot)) {
22	    if (-not (Test-Path $path)) {
23	        New-Item -ItemType Directory -Path $path -Force | Out-Null
24	    }
25	}
26	
27	function Write-Log {
28	    param([string]$Msg, [string]$Type = "INFO")
29	
30	    $Line = "[$(Get-Date -Format 'HH:mm:ss')] [$Type] $Msg"
31	    $Color = switch ($Type) {
32	        "ERROR"   { "Red" }
33	        "SUCCESS" { "Green" }
34	        "WARNING" { "Yellow" }
35	        "DEBUG"   { "Cyan" }
36	        Default   { "Gray" }
37	    }
38	
39	    Write-Host $Line -ForegroundColor $Color
40	    $Line | Out-File -FilePath $FullLogPath -Append -Encoding UTF8 -ErrorAction SilentlyContinue
41	}
42	
43	function Clean-OldResources {
44	    Write-Log "Nettoyage des anciens logs et temporaires..." "INFO"
45	
46	    if (Test-Path $TempExtractRoot) {
47	        # Le verrou d’exécution garantit qu’aucun autre cycle n’est actif :
48	        # tout Ext_* ou 7zWork_* restant provient donc d’un cycle interrompu.
49	        $StaleTempDirs = @(Get-ChildItem -Path $TempExtractRoot -Directory -ErrorAction SilentlyContinue |
50	            Where-Object { $_.Name -like "Ext_*" -or $_.Name -like "7zWork_*" })
51	
52	        if ($StaleTempDirs.Count -gt 0) {
53	            Write-Log "Purge de $($StaleTempDirs.Count) dossier(s) temporaire(s) laissé(s) par un ancien cycle..." "WARNING"
54	            $StaleTempDirs | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
55	        }
56	    }
57	
58	    if (Test-Path $LogPath) {
59	        Get-ChildItem -Path $LogPath -Filter "*.log" -ErrorAction SilentlyContinue |
60	            Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-15) } |
61	            Remove-Item -Force -ErrorAction SilentlyContinue
62	    }
63	}
64	
65	function Get-TempStorageStatus {
66	    try {
67	        $root = [IO.Path]::GetPathRoot($TempExtractRoot)
68	        $drive = New-Object -TypeName System.IO.DriveInfo -ArgumentList $root
69	
70	        return [pscustomobject]@{
71	            FreeBytes  = [int64]$drive.AvailableFreeSpace
72	            TotalBytes = [int64]$drive.TotalSize
73	            FreeGB     = [math]::Round($drive.AvailableFreeSpace / 1GB, 2)
74	            TotalGB    = [math]::Round($drive.TotalSize / 1GB, 2)
75	        }
76	    }
77	    catch {
78	        return $null
79	    }
80	}
81	
82	function Get-CredentialFromFile {
83	    param([string]$CredFilePath)
84	
85	    if (-not (Test-Path $CredFilePath)) {
86	        throw "Fichier .cred introuvable : $CredFilePath"
87	    }
88	
89	    $raw = (Get-Content -Path $CredFilePath -Raw -ErrorAction Stop).Trim()
90	
91	    if ([string]::IsNullOrWhiteSpace($raw)) {
92	        throw "Fichier .cred vide : $CredFilePath"
93	    }
94	
95	    try {
96	        $SecureString = $raw | ConvertTo-SecureString -ErrorAction Stop
97	    }
98	    catch {
99	        throw "Impossible de déchiffrer $CredFilePath. Détail : $($_.Exception.Message)"
100	    }
101	
102	    $BSTR = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($SecureString)
103	    try {
104	        return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($BSTR)
105	    }
106	    finally {
107	        [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($BSTR)
108	    }
109	}
110	
111	function Get-StateFilePath {
112	    param([string]$MachineName)
113	    Join-Path $StateRoot "$MachineName.json"
114	}
115	
116	function Read-MachineState {
117	    param([string]$MachineName)
118	
119	    $StateFile = Get-StateFilePath -MachineName $MachineName
120	    if (-not (Test-Path $StateFile)) { return $null }
121	
122	    try {
123	        Get-Content -Raw -Path $StateFile -Encoding UTF8 | ConvertFrom-Json
124	    } catch {
125	        return $null
126	    }
127	}
128	
129	function Write-MachineState {
130	    param(
131	        [string]$MachineName,
132	        [hashtable]$Data
133	    )
134	
135	    $StateFile = Get-StateFilePath -MachineName $MachineName
136	    $Data | ConvertTo-Json -Depth 8 | Out-File -FilePath $StateFile -Encoding UTF8 -Force
137	}
138	
139	function Get-ServerVersionSignature {
140	    param([object]$ZipFile)
141	    "{0}|{1}|{2}" -f $ZipFile.Name, $ZipFile.Length, $ZipFile.LastWriteTimeUtc.ToString("o")
142	}
143	
144	# Le scan d’un dossier UNC est exécuté dans un processus séparé. Si Windows/SMB
145	# reste bloqué, le processus est arrêté sans immobiliser tout le cycle.
146	$SourceScanWorkerScript = @'
147	$ErrorActionPreference = "Stop"
148	
149	try {
150	    $folder = $env:PROCDEG_SCAN_PATH
151	
152	    if (-not (Test-Path -LiteralPath $folder)) {
153	        @{ Status = "Missing" } | ConvertTo-Json -Compress
154	        exit 0
155	    }
156	
157	    $files = @(Get-ChildItem -LiteralPath $folder -File -ErrorAction Stop)
158	    $ok    = $files | Where-Object { $_.Extension -ieq ".ok" }  | Select-Object -First 1
159	    $zip   = $files | Where-Object { $_.Extension -ieq ".zip" } | Select-Object -First 1
160	
161	    $zipData = $null
162	    if ($zip) {
163	        $zipData = @{
164	            FullName         = $zip.FullName
165	            Name             = $zip.Name
166	            Length           = [int64]$zip.Length
167	            LastWriteTimeUtc = $zip.LastWriteTimeUtc.ToString("o")
168	        }
169	    }
170	
171	    @{
172	        Status = "OK"
173	        HasOk  = [bool]$ok
174	        Zip    = $zipData
175	    } | ConvertTo-Json -Depth 4 -Compress
176	}
177	catch {
178	    @{
179	        Status  = "Error"
180	        Message = $_.Exception.Message
181	    } | ConvertTo-Json -Compress
182	    exit 1
183	}
184	'@
185	
186	$SourceScanEncodedCommand = [Convert]::ToBase64String(
187	    [Text.Encoding]::Unicode.GetBytes($SourceScanWorkerScript)
188	)
189	
190	function Get-SourceLotWithTimeout {
191	    param(
192	        [string]$FolderPath,
193	        [int]$TimeoutSec
194	    )
195	
196	    $scanId     = [Guid]::NewGuid().ToString("N")
197	    $scanStdOut = Join-Path $env:TEMP "procdeg_scan_$scanId.out.log"
198	    $scanStdErr = Join-Path $env:TEMP "procdeg_scan_$scanId.err.log"
199	    $scanProc   = $null
200	
201	    try {
202	        # Le processus enfant hérite de cette variable au démarrage.
203	        $env:PROCDEG_SCAN_PATH = $FolderPath
204	
205	        $scanStartInfo = @{
206	            FilePath               = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
207	            ArgumentList           = @(
208	                "-NoLogo"
209	                "-NoProfile"
210	                "-NonInteractive"
211	                "-ExecutionPolicy"
212	                "Bypass"
213	                "-EncodedCommand"
214	                $SourceScanEncodedCommand
215	            )
216	            WindowStyle            = "Hidden"
217	            PassThru               = $true
218	            RedirectStandardOutput = $scanStdOut
219	            RedirectStandardError  = $scanStdErr
220	        }
221	
222	        $scanProc = Start-Process @scanStartInfo
223	    }
224	    catch {
225	        return [pscustomobject]@{
226	            Status  = "Error"
227	            Message = "Impossible de démarrer le scanner : $($_.Exception.Message)"
228	        }
229	    }
230	    finally {
231	        Remove-Item Env:PROCDEG_SCAN_PATH -ErrorAction SilentlyContinue
232	    }
233	
234	    try {
235	        $finished = $scanProc.WaitForExit($TimeoutSec * 1000)
236	
237	        if (-not $finished) {
238	            try { $scanProc.Kill() } catch {}
239	            try { $scanProc.WaitForExit() } catch {}
240	
241	            return [pscustomobject]@{
242	                Status  = "Timeout"
243	                Message = "Lecture du dossier source supérieure à $TimeoutSec s"
244	            }
245	        }
246	
247	        $scanProc.WaitForExit()
248	        $scanProc.Refresh()
249	
250	        $output = if (Test-Path $scanStdOut) {
251	            (Get-Content -Raw -Path $scanStdOut -ErrorAction SilentlyContinue).Trim()
252	        } else { "" }
253	
254	        $errorOutput = if (Test-Path $scanStdErr) {
255	            (Get-Content -Raw -Path $scanStdErr -ErrorAction SilentlyContinue).Trim()
256	        } else { "" }
257	
258	        if ([string]::IsNullOrWhiteSpace($output)) {
259	            return [pscustomobject]@{
260	                Status  = "Error"
261	                Message = if ($errorOutput) { $errorOutput } else { "Le scanner du dossier source n’a retourné aucun résultat" }
262	            }
263	        }
264	
265	        try {
266	            return $output | ConvertFrom-Json -ErrorAction Stop
267	        }
268	        catch {
269	            return [pscustomobject]@{
270	                Status  = "Error"
271	                Message = "Résultat du scanner illisible : $output"
272	            }
273	        }
274	    }
275	    finally {
276	        Remove-Item $scanStdOut, $scanStdErr -Force -ErrorAction SilentlyContinue
277	        if ($scanProc) { $scanProc.Dispose() }
