281	function Connect-SourceShareWithTimeout {
282	    param(
283	        [string]$SourcePath,
284	        [string]$User,
285	        [string]$Password,
286	        [int]$TimeoutSec
287	    )
288	
289	    $mountId     = [Guid]::NewGuid().ToString("N")
290	    $mountStdOut = Join-Path $env:TEMP "procdeg_mount_$mountId.out.log"
291	    $mountStdErr = Join-Path $env:TEMP "procdeg_mount_$mountId.err.log"
292	    $mountProc   = $null
293	
294	    try {
295	        $mountStartInfo = @{
296	            FilePath               = "net.exe"
297	            ArgumentList           = @("use", $SourcePath, "/user:$User", $Password, "/persistent:no")
298	            WindowStyle            = "Hidden"
299	            PassThru               = $true
300	            RedirectStandardOutput = $mountStdOut
301	            RedirectStandardError  = $mountStdErr
302	        }
303	
304	        $mountProc = Start-Process @mountStartInfo
305	        $finished = $mountProc.WaitForExit($TimeoutSec * 1000)
306	
307	        if (-not $finished) {
308	            try { $mountProc.Kill() } catch {}
309	            try { $mountProc.WaitForExit() } catch {}
310	
311	            return [pscustomobject]@{
312	                Success = $false
313	                Timeout = $true
314	                Detail  = "Timeout du montage après $TimeoutSec s"
315	            }
316	        }
317	
318	        $mountProc.WaitForExit()
319	        $mountProc.Refresh()
320	
321	        $stdOut = if (Test-Path $mountStdOut) { Get-Content -Raw $mountStdOut -ErrorAction SilentlyContinue } else { "" }
322	        $stdErr = if (Test-Path $mountStdErr) { Get-Content -Raw $mountStdErr -ErrorAction SilentlyContinue } else { "" }
323	        $detail = ($stdOut + $stdErr).Trim()
324	
325	        # Sur certaines versions de Windows PowerShell, ExitCode peut être vide
326	        # après WaitForExit(timeout) malgré la réussite de net.exe. On accepte
327	        # donc aussi le message officiel de succès, en français ou en anglais.
328	        $exitCode = $null
329	        try { $exitCode = $mountProc.ExitCode } catch {}
330	
331	        $successMessage = (
332	            $detail -match "(?i)commande.*correctement" -or
333	            $detail -match "(?i)command.*completed.*successfully"
334	        )
335	
336	        $mountSucceeded = ($exitCode -eq 0) -or $successMessage
337	
338	        return [pscustomobject]@{
339	            Success  = $mountSucceeded
340	            Timeout = $false
341	            ExitCode = $exitCode
342	            Detail   = $detail
343	        }
344	    }
345	    catch {
346	        return [pscustomobject]@{
347	            Success = $false
348	            Timeout = $false
349	            Detail  = $_.Exception.Message
350	        }
351	    }
352	    finally {
353	        Remove-Item $mountStdOut, $mountStdErr -Force -ErrorAction SilentlyContinue
354	        if ($mountProc) { $mountProc.Dispose() }
355	    }
356	}
