#requires -version 5.1

# ==============================================================================
# SYNCHRONISATION PROCÉDURE DÉGRADÉE - MODE CONVERGENCE AVEC .CRED
# ==============================================================================

$jsonPath         = "C:\ProcDeg\Config\planning.json"
$MaxThreads       = 5
$7zPath           = "C:\Program Files\7-Zip\7z.exe"
$LogPath          = "C:\ProcDeg\Logs"
$TempExtractRoot  = "C:\ProcDeg\Temp"
$StateRoot        = "C:\ProcDeg\State"
$RunLockPath      = "C:\ProcDeg\Config\run.lock"
$GlobalTimeoutSec = 840
$SourceMountTimeoutSec = 20
$SourceScanTimeoutSec  = 10

$LogFileName = "Deploy_$($PID)_$(Get-Date -Format 'yyyy-MM-dd_HH-mm-ss').log"
$FullLogPath = Join-Path $LogPath $LogFileName

foreach ($path in @($LogPath, $TempExtractRoot, $StateRoot)) {
    if (-not (Test-Path $path)) {
        New-Item -ItemType Directory -Path $path -Force | Out-Null
    }
}

function Write-Log {
    param([string]$Msg, [string]$Type = "INFO")

    $Line = "[$(Get-Date -Format 'HH:mm:ss')] [$Type] $Msg"
    $Color = switch ($Type) {
        "ERROR"   { "Red" }
        "SUCCESS" { "Green" }
        "WARNING" { "Yellow" }
        "DEBUG"   { "Cyan" }
        Default   { "Gray" }
    }

    Write-Host $Line -ForegroundColor $Color
    $Line | Out-File -FilePath $FullLogPath -Append -Encoding UTF8 -ErrorAction SilentlyContinue
}

function Clean-OldResources {
    Write-Log "Nettoyage des anciens logs et temporaires..." "INFO"

    if (Test-Path $TempExtractRoot) {
        # Le verrou d’exécution garantit qu’aucun autre cycle n’est actif :
        # tout Ext_* ou 7zWork_* restant provient donc d’un cycle interrompu.
        $StaleTempDirs = @(Get-ChildItem -Path $TempExtractRoot -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -like "Ext_*" -or $_.Name -like "7zWork_*" })

        if ($StaleTempDirs.Count -gt 0) {
            Write-Log "Purge de $($StaleTempDirs.Count) dossier(s) temporaire(s) laissé(s) par un ancien cycle..." "WARNING"
            $StaleTempDirs | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    if (Test-Path $LogPath) {
        Get-ChildItem -Path $LogPath -Filter "*.log" -ErrorAction SilentlyContinue |
            Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-15) } |
            Remove-Item -Force -ErrorAction SilentlyContinue
    }
}

function Get-TempStorageStatus {
    try {
        $root = [IO.Path]::GetPathRoot($TempExtractRoot)
        $drive = New-Object -TypeName System.IO.DriveInfo -ArgumentList $root

        return [pscustomobject]@{
            FreeBytes  = [int64]$drive.AvailableFreeSpace
            TotalBytes = [int64]$drive.TotalSize
            FreeGB     = [math]::Round($drive.AvailableFreeSpace / 1GB, 2)
            TotalGB    = [math]::Round($drive.TotalSize / 1GB, 2)
        }
    }
    catch {
        return $null
    }
}

function Get-CredentialFromFile {
    param([string]$CredFilePath)

    if (-not (Test-Path $CredFilePath)) {
        throw "Fichier .cred introuvable : $CredFilePath"
    }

    $raw = (Get-Content -Path $CredFilePath -Raw -ErrorAction Stop).Trim()

    if ([string]::IsNullOrWhiteSpace($raw)) {
        throw "Fichier .cred vide : $CredFilePath"
    }

    try {
        $SecureString = $raw | ConvertTo-SecureString -ErrorAction Stop
    }
    catch {
        throw "Impossible de déchiffrer $CredFilePath. Détail : $($_.Exception.Message)"
    }

    $BSTR = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($SecureString)
    try {
        return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($BSTR)
    }
    finally {
        [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($BSTR)
    }
}

function Get-StateFilePath {
    param([string]$MachineName)
    Join-Path $StateRoot "$MachineName.json"
}

function Read-MachineState {
    param([string]$MachineName)

    $StateFile = Get-StateFilePath -MachineName $MachineName
    if (-not (Test-Path $StateFile)) { return $null }

    try {
        Get-Content -Raw -Path $StateFile -Encoding UTF8 | ConvertFrom-Json
    } catch {
        return $null
    }
}

function Write-MachineState {
    param(
        [string]$MachineName,
        [hashtable]$Data
    )

    $StateFile = Get-StateFilePath -MachineName $MachineName
    $Data | ConvertTo-Json -Depth 8 | Out-File -FilePath $StateFile -Encoding UTF8 -Force
}

function Get-ServerVersionSignature {
    param([object]$ZipFile)
    "{0}|{1}|{2}" -f $ZipFile.Name, $ZipFile.Length, $ZipFile.LastWriteTimeUtc.ToString("o")
}

# Le scan d’un dossier UNC est exécuté dans un processus séparé. Si Windows/SMB
# reste bloqué, le processus est arrêté sans immobiliser tout le cycle.
$SourceScanWorkerScript = @'
$ErrorActionPreference = "Stop"

try {
    $folder = $env:PROCDEG_SCAN_PATH

    if (-not (Test-Path -LiteralPath $folder)) {
        @{ Status = "Missing" } | ConvertTo-Json -Compress
        exit 0
    }

    $files = @(Get-ChildItem -LiteralPath $folder -File -ErrorAction Stop)
    $ok    = $files | Where-Object { $_.Extension -ieq ".ok" }  | Select-Object -First 1
    $zip   = $files | Where-Object { $_.Extension -ieq ".zip" } | Select-Object -First 1

    $zipData = $null
    if ($zip) {
        $zipData = @{
            FullName         = $zip.FullName
            Name             = $zip.Name
            Length           = [int64]$zip.Length
            LastWriteTimeUtc = $zip.LastWriteTimeUtc.ToString("o")
        }
    }

    @{
        Status = "OK"
        HasOk  = [bool]$ok
        Zip    = $zipData
    } | ConvertTo-Json -Depth 4 -Compress
}
catch {
    @{
        Status  = "Error"
        Message = $_.Exception.Message
    } | ConvertTo-Json -Compress
    exit 1
}
'@

$SourceScanEncodedCommand = [Convert]::ToBase64String(
    [Text.Encoding]::Unicode.GetBytes($SourceScanWorkerScript)
)

function Get-SourceLotWithTimeout {
    param(
        [string]$FolderPath,
        [int]$TimeoutSec
    )

    $scanId     = [Guid]::NewGuid().ToString("N")
    $scanStdOut = Join-Path $env:TEMP "procdeg_scan_$scanId.out.log"
    $scanStdErr = Join-Path $env:TEMP "procdeg_scan_$scanId.err.log"
    $scanProc   = $null

    try {
        # Le processus enfant hérite de cette variable au démarrage.
        $env:PROCDEG_SCAN_PATH = $FolderPath

        $scanStartInfo = @{
            FilePath               = "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
            ArgumentList           = @(
                "-NoLogo"
                "-NoProfile"
                "-NonInteractive"
                "-ExecutionPolicy"
                "Bypass"
                "-EncodedCommand"
                $SourceScanEncodedCommand
            )
            WindowStyle            = "Hidden"
            PassThru               = $true
            RedirectStandardOutput = $scanStdOut
            RedirectStandardError  = $scanStdErr
        }

        $scanProc = Start-Process @scanStartInfo
    }
    catch {
        return [pscustomobject]@{
            Status  = "Error"
            Message = "Impossible de démarrer le scanner : $($_.Exception.Message)"
        }
    }
    finally {
        Remove-Item Env:PROCDEG_SCAN_PATH -ErrorAction SilentlyContinue
    }

    try {
        $finished = $scanProc.WaitForExit($TimeoutSec * 1000)

        if (-not $finished) {
            try { $scanProc.Kill() } catch {}
            try { $scanProc.WaitForExit() } catch {}

            return [pscustomobject]@{
                Status  = "Timeout"
                Message = "Lecture du dossier source supérieure à $TimeoutSec s"
            }
        }

        $scanProc.WaitForExit()
        $scanProc.Refresh()

        $output = if (Test-Path $scanStdOut) {
            (Get-Content -Raw -Path $scanStdOut -ErrorAction SilentlyContinue).Trim()
        } else { "" }

        $errorOutput = if (Test-Path $scanStdErr) {
            (Get-Content -Raw -Path $scanStdErr -ErrorAction SilentlyContinue).Trim()
        } else { "" }

        if ([string]::IsNullOrWhiteSpace($output)) {
            return [pscustomobject]@{
                Status  = "Error"
                Message = if ($errorOutput) { $errorOutput } else { "Le scanner du dossier source n’a retourné aucun résultat" }
            }
        }

        try {
            return $output | ConvertFrom-Json -ErrorAction Stop
        }
        catch {
            return [pscustomobject]@{
                Status  = "Error"
                Message = "Résultat du scanner illisible : $output"
            }
        }
    }
    finally {
        Remove-Item $scanStdOut, $scanStdErr -Force -ErrorAction SilentlyContinue
        if ($scanProc) { $scanProc.Dispose() }
    }
}

function Connect-SourceShareWithTimeout {
    param(
        [string]$SourcePath,
        [string]$User,
        [string]$Password,
        [int]$TimeoutSec
    )

    $mountId     = [Guid]::NewGuid().ToString("N")
    $mountStdOut = Join-Path $env:TEMP "procdeg_mount_$mountId.out.log"
    $mountStdErr = Join-Path $env:TEMP "procdeg_mount_$mountId.err.log"
    $mountProc   = $null

    try {
        $mountStartInfo = @{
            FilePath               = "net.exe"
            ArgumentList           = @("use", $SourcePath, "/user:$User", $Password, "/persistent:no")
            WindowStyle            = "Hidden"
            PassThru               = $true
            RedirectStandardOutput = $mountStdOut
            RedirectStandardError  = $mountStdErr
        }

        $mountProc = Start-Process @mountStartInfo
        $finished = $mountProc.WaitForExit($TimeoutSec * 1000)

        if (-not $finished) {
            try { $mountProc.Kill() } catch {}
            try { $mountProc.WaitForExit() } catch {}

            return [pscustomobject]@{
                Success = $false
                Timeout = $true
                Detail  = "Timeout du montage après $TimeoutSec s"
            }
        }

        $mountProc.WaitForExit()
        $mountProc.Refresh()

        $stdOut = if (Test-Path $mountStdOut) { Get-Content -Raw $mountStdOut -ErrorAction SilentlyContinue } else { "" }
        $stdErr = if (Test-Path $mountStdErr) { Get-Content -Raw $mountStdErr -ErrorAction SilentlyContinue } else { "" }
        $detail = ($stdOut + $stdErr).Trim()

        # Sur certaines versions de Windows PowerShell, ExitCode peut être vide
        # après WaitForExit(timeout) malgré la réussite de net.exe. On accepte
        # donc aussi le message officiel de succès, en français ou en anglais.
        $exitCode = $null
        try { $exitCode = $mountProc.ExitCode } catch {}

        $successMessage = (
            $detail -match "(?i)commande.*correctement" -or
            $detail -match "(?i)command.*completed.*successfully"
        )

        $mountSucceeded = ($exitCode -eq 0) -or $successMessage

        return [pscustomobject]@{
            Success  = $mountSucceeded
            Timeout = $false
            ExitCode = $exitCode
            Detail   = $detail
        }
    }
    catch {
        return [pscustomobject]@{
            Success = $false
            Timeout = $false
            Detail  = $_.Exception.Message
        }
    }
    finally {
        Remove-Item $mountStdOut, $mountStdErr -Force -ErrorAction SilentlyContinue
        if ($mountProc) { $mountProc.Dispose() }
    }
}

function Acquire-RunLock {
    if (Test-Path $RunLockPath) {
        try {
            $lockData = Get-Content -Raw -Path $RunLockPath | ConvertFrom-Json
            $lockPid  = [int]$lockData.PID
            $proc     = Get-Process -Id $lockPid -ErrorAction SilentlyContinue

            if ($proc) {
                Write-Log "Une autre instance semble déjà active. PID=$lockPid" "WARNING"
                return $false
            } else {
                Remove-Item -Path $RunLockPath -Force -ErrorAction SilentlyContinue
            }
        }
        catch {
            Remove-Item -Path $RunLockPath -Force -ErrorAction SilentlyContinue
        }
    }

    @{
        PID       = $PID
        CreatedAt = (Get-Date).ToString("o")
    } | ConvertTo-Json | Out-File -FilePath $RunLockPath -Encoding UTF8 -Force

    return $true
}

function Release-RunLock {
    Remove-Item -Path $RunLockPath -Force -ErrorAction SilentlyContinue
}

if (-not (Acquire-RunLock)) {
    exit
}

try {
    $CycleStart = Get-Date
    Write-Log "--- DÉMARRAGE DU CYCLE (PID: $PID) ---"
    Clean-OldResources
    $InitialStorage = Get-TempStorageStatus
    if ($InitialStorage) {
        Write-Log "Stockage temporaire : $TempExtractRoot — $($InitialStorage.FreeGB) Go libres sur $($InitialStorage.TotalGB) Go." "INFO"
    }
    Write-Log "Utilisateur courant : $([System.Security.Principal.WindowsIdentity]::GetCurrent().Name)" "INFO"
    Write-Log "Utilisateur whoami : $(whoami)" "INFO"
    Write-Log "Machine : $env:COMPUTERNAME" "INFO"

    if (-not (Test-Path $jsonPath)) {
        Write-Log "Fichier JSON introuvable : $jsonPath" "ERROR"
        exit
    }

    try {
        $config = Get-Content -Raw -Path $jsonPath -Encoding UTF8 | ConvertFrom-Json
    } catch {
        Write-Log "Erreur de lecture du JSON : $($_.Exception.Message)" "ERROR"
        exit
    }

    $WorkQueue     = New-Object System.Collections.ArrayList
    $MappedSources = @{}
    $MountErrors   = 0
    $ScanStoppedByGlobalTimeout = $false
    $AlreadyUpToDateCount = 0
    $NoSourceFolderCount  = 0
    $NoValidLotCount      = 0
    $ScanIssueCount       = 0

    $EligibleMachines = @($config.Affectations | Where-Object {
        -not [string]::IsNullOrWhiteSpace($_.Pattern) -and $null -eq $_._S_
    })
    $TotalMachines = $EligibleMachines.Count
    $ScanIndex     = 0

    Write-Log "Scan des affectations : $TotalMachines machine(s) à contrôler..." "INFO"

    foreach ($machine in $EligibleMachines) {
        if (((Get-Date) - $CycleStart).TotalSeconds -ge $GlobalTimeoutSec) {
            $ScanStoppedByGlobalTimeout = $true
            Write-Log "TIMEOUT GLOBAL atteint pendant le scan des affectations." "WARNING"
            break
        }

        $nomMachine = $machine.Pattern
        $idDomaine  = $machine.DomainID
        $ScanIndex++
        # Progression synthétique : première machine, puis toutes les 10 et la dernière.
        if ($ScanIndex -eq 1 -or $ScanIndex -eq $TotalMachines -or ($ScanIndex % 10) -eq 0) {
            Write-Log "Scan des lots : $ScanIndex/$TotalMachines contrôlés..." "DEBUG"
        }

        $domaineInfo = $config.Domaines.$idDomaine
        if (-not $domaineInfo) {
            $ScanIssueCount++
            Write-Log "Domaine introuvable pour $nomMachine : $idDomaine" "ERROR"
            continue
        }

        $sourceConfig = $config.Sources.($domaineInfo.SourceID)
        if (-not $sourceConfig) {
            $ScanIssueCount++
            Write-Log "Source introuvable pour $nomMachine : $($domaineInfo.SourceID)" "ERROR"
            continue
        }

        $sourcePath      = $sourceConfig.Path
        $srvUser         = $sourceConfig.User
        $srvCredFile     = $sourceConfig.CredFile
        $pcUser          = $domaineInfo.User
        $pcCredFile      = $domaineInfo.CredFile
        $suffixeDNS      = $domaineInfo.Suffix
        $TargetFQDN      = "$nomMachine.$suffixeDNS"

        # Par défaut, on contacte le poste via son FQDN habituel.
        # Pour un poste NATé, l'affectation peut définir un TargetHost spécifique
        # (IP NAT ou nom DNS joignable depuis ce serveur).
        $TargetHost = if (
            $machine.PSObject.Properties.Name -contains "TargetHost" -and
            -not [string]::IsNullOrWhiteSpace([string]$machine.TargetHost)
        ) {
            ([string]$machine.TargetHost).Trim()
        } else {
            $TargetFQDN
        }

        if ($TargetHost -ne $TargetFQDN) {
            Write-Log "$nomMachine : cible réseau spécifique (NAT) = $TargetHost ; FQDN logique = $TargetFQDN" "DEBUG"
        }

        $pcUserLogin     = "$pcUser@$suffixeDNS"
        $DossierPCSource = Join-Path $sourcePath $nomMachine

        if (-not $MappedSources.ContainsKey($sourcePath)) {
            try {
                Write-Log "Montage du partage source $sourcePath (timeout ${SourceMountTimeoutSec}s)..." "DEBUG"
                $srvPassword = Get-CredentialFromFile -CredFilePath $srvCredFile
                $mountResult = Connect-SourceShareWithTimeout `
                    -SourcePath $sourcePath `
                    -User $srvUser `
                    -Password $srvPassword `
                    -TimeoutSec $SourceMountTimeoutSec
                $srvPassword = $null

                if (-not $mountResult.Success) {
                    throw "net use a échoué (ExitCode=$($mountResult.ExitCode)) : $($mountResult.Detail)"
                }

                $MappedSources[$sourcePath] = $true
                Write-Log "Partage source monté : $sourcePath" "DEBUG"
            } catch {
                $MappedSources[$sourcePath] = $false
                $MountErrors++
                $ScanIssueCount++
                Write-Log "Impossible de monter le partage source $sourcePath : $($_.Exception.Message)" "ERROR"
                continue
            }
        }
        elseif (-not $MappedSources[$sourcePath]) {
            $ScanIssueCount++
            continue
        }

        $state = Read-MachineState -MachineName $nomMachine

        $baseState = @{
            Machine     = $nomMachine
            FQDN        = $TargetFQDN
            DomainID    = $idDomaine
            SourcePath  = $sourcePath
            LastSeenUtc = (Get-Date).ToUniversalTime().ToString("o")
        }

        $sourceLot = Get-SourceLotWithTimeout `
            -FolderPath $DossierPCSource `
            -TimeoutSec $SourceScanTimeoutSec

        if ($sourceLot.Status -eq "Timeout") {
            $ScanIssueCount++
            Write-MachineState -MachineName $nomMachine -Data ($baseState + @{
                LastResult            = "SourceScanTimeout"
                LastMessage           = "Timeout de lecture du dossier source (> ${SourceScanTimeoutSec}s)"
                LastServerVersion     = $null
                LastServerZipName     = $null
                LastServerZipWriteUtc = $null
                LastErrorUtc          = (Get-Date).ToUniversalTime().ToString("o")
            })
            Write-Log "Scan $ScanIndex/$TotalMachines : $nomMachine ignoré, timeout du dossier source (> ${SourceScanTimeoutSec}s)" "WARNING"
            continue
        }

        if ($sourceLot.Status -eq "Error") {
            $ScanIssueCount++
            Write-MachineState -MachineName $nomMachine -Data ($baseState + @{
                LastResult            = "SourceScanError"
                LastMessage           = $sourceLot.Message
                LastServerVersion     = $null
                LastServerZipName     = $null
                LastServerZipWriteUtc = $null
                LastErrorUtc          = (Get-Date).ToUniversalTime().ToString("o")
            })
            Write-Log "Scan $ScanIndex/$TotalMachines : erreur de lecture pour $nomMachine : $($sourceLot.Message)" "ERROR"
            continue
        }

        if ($sourceLot.Status -eq "Missing") {
            $NoSourceFolderCount++
            Write-MachineState -MachineName $nomMachine -Data ($baseState + @{
                LastResult            = "NoSourceFolder"
                LastMessage           = "Dossier source absent"
                LastServerVersion     = $null
                LastServerZipName     = $null
                LastServerZipWriteUtc = $null
            })
            continue
        }

        $HasOk  = [bool]$sourceLot.HasOk
        $HasZip = $null

        if ($sourceLot.Zip) {
            try {
                $zipWriteUtc = [DateTime]::Parse(
                    [string]$sourceLot.Zip.LastWriteTimeUtc,
                    [Globalization.CultureInfo]::InvariantCulture,
                    [Globalization.DateTimeStyles]::RoundtripKind
                ).ToUniversalTime()

                $HasZip = [pscustomobject]@{
                    FullName         = [string]$sourceLot.Zip.FullName
                    Name             = [string]$sourceLot.Zip.Name
                    Length           = [int64]$sourceLot.Zip.Length
                    LastWriteTimeUtc = $zipWriteUtc
                }
            }
            catch {
                $ScanIssueCount++
                Write-Log "Scan $ScanIndex/$TotalMachines : métadonnées ZIP invalides pour $nomMachine" "ERROR"
                continue
            }
        }

        if (-not $HasZip -or -not $HasOk) {
            $NoValidLotCount++
            Write-MachineState -MachineName $nomMachine -Data ($baseState + @{
                LastResult            = "NoValidLot"
                LastMessage           = "Lot non prêt (zip ou ok absent)"
                LastServerVersion     = $null
                LastServerZipName     = if ($HasZip) { $HasZip.Name } else { $null }
                LastServerZipWriteUtc = if ($HasZip) { $HasZip.LastWriteTimeUtc.ToString("o") } else { $null }
            })
            continue
        }

        $serverVersion = Get-ServerVersionSignature -ZipFile $HasZip
        $lastDeployVersion = if ($state) { $state.LastDeployVersion } else { $null }

        Write-MachineState -MachineName $nomMachine -Data ($baseState + @{
            LastServerVersion      = $serverVersion
            LastServerZipName      = $HasZip.Name
            LastServerZipWriteUtc  = $HasZip.LastWriteTimeUtc.ToString("o")
            LastServerZipSize      = $HasZip.Length
            LastSeenServerUtc      = (Get-Date).ToUniversalTime().ToString("o")
            LastResult             = if ($state) { $state.LastResult } else { "Detected" }
            LastMessage            = if ($state) { $state.LastMessage } else { "Lot détecté" }
            LastDeployVersion      = if ($state) { $state.LastDeployVersion } else { $null }
            LastDeployUtc          = if ($state) { $state.LastDeployUtc } else { $null }
            LastPcReachableUtc     = if ($state) { $state.LastPcReachableUtc } else { $null }
            LastErrorUtc           = if ($state) { $state.LastErrorUtc } else { $null }
        })

        if ($serverVersion -eq $lastDeployVersion) {
            $AlreadyUpToDateCount++
            continue
        }

        $null = $WorkQueue.Add(@{
            Machine           = $nomMachine
            FQDN              = $TargetFQDN
            TargetHost        = $TargetHost
            UserLogin         = $pcUserLogin
            CredFile          = $pcCredFile
            SourceZip         = $HasZip.FullName
            SourceZipName     = $HasZip.Name
            SourceZipSize     = $HasZip.Length
            SourceZipWriteUtc = $HasZip.LastWriteTimeUtc.ToString("o")
            SourceVersion     = $serverVersion
            DomainID          = $idDomaine
            SourcePath        = $sourcePath
            StateRoot         = $StateRoot
        })
    }

    if ($ScanStoppedByGlobalTimeout) {
        foreach ($path in $MappedSources.Keys) {
            if ($MappedSources[$path]) {
                net use "$path" /delete /y 2>&1 | Out-Null
            }
        }
        Write-Log "--- FIN DU CYCLE (timeout pendant le scan) ---" "WARNING"
        exit
    }

    $ScanDurationSec = [math]::Round(((Get-Date) - $CycleStart).TotalSeconds, 1)
    Write-Log "Scan terminé en ${ScanDurationSec}s : $($WorkQueue.Count) à synchroniser, $AlreadyUpToDateCount à jour, $NoSourceFolderCount sans dossier, $NoValidLotCount lot(s) incomplet(s), $ScanIssueCount incident(s)." "INFO"

    if ($WorkQueue.Count -eq 0) {
        if ($MountErrors -gt 0) {
            Write-Log "Aucune synchronisation possible car aucun partage source n'a pu être monté correctement." "WARNING"
        } else {
            Write-Log "Aucune synchronisation nécessaire." "SUCCESS"
        }

        foreach ($path in $MappedSources.Keys) {
            if ($MappedSources[$path]) {
                net use "$path" /delete /y 2>&1 | Out-Null
            }
        }
        exit
    }

    $ScriptBlock = {
        param($Job, $TempRoot, $7zExe)

        $ExtractedBytes    = [int64]0
        $ExtractedFileCount = 0
        $CopyStartedAt     = $null
        $CleanupAnnounced  = $false

        function Publish-JobProgress {
            param(
                [string]$Stage,
                [string]$Message,
                [string]$Type = "DEBUG"
            )

            Write-Information -MessageData ([pscustomobject]@{
                Kind    = "ProcDegProgress"
                PC      = $Job.FQDN
                Stage   = $Stage
                Message = $Message
                Type    = $Type
                TimeUtc = (Get-Date).ToUniversalTime().ToString("o")
            }) -Tags "ProcDegProgress" -InformationAction Continue
        }

        function Format-ByteSize {
            param([int64]$Bytes)

            if ($Bytes -ge 1GB) { return "$([math]::Round($Bytes / 1GB, 2)) Go" }
            if ($Bytes -ge 1MB) { return "$([math]::Round($Bytes / 1MB, 1)) Mo" }
            if ($Bytes -ge 1KB) { return "$([math]::Round($Bytes / 1KB, 1)) Ko" }
            return "$Bytes octets"
        }

        function Write-State {
            param([hashtable]$StateData)
            $StateFile = Join-Path $Job.StateRoot "$($Job.Machine).json"
            $StateData | ConvertTo-Json -Depth 8 | Out-File -FilePath $StateFile -Encoding UTF8 -Force
        }

        function Get-CredentialFromFile {
            param([string]$CredFilePath)

            if (-not (Test-Path $CredFilePath)) {
                throw "Fichier .cred introuvable : $CredFilePath"
            }

            $raw = (Get-Content -Path $CredFilePath -Raw -ErrorAction Stop).Trim()

            if ([string]::IsNullOrWhiteSpace($raw)) {
                throw "Fichier .cred vide : $CredFilePath"
            }

            try {
                $SecureString = $raw | ConvertTo-SecureString -ErrorAction Stop
            }
            catch {
                throw "Impossible de déchiffrer $CredFilePath. Détail : $($_.Exception.Message)"
            }

            $BSTR = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($SecureString)
            try {
                return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($BSTR)
            }
            finally {
                [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($BSTR)
            }
        }

        function Remove-TempDirectoryWithRetry {
            param([string]$Path)

            if ([string]::IsNullOrWhiteSpace($Path)) { return $true }

            for ($attempt = 1; $attempt -le 5; $attempt++) {
                if (-not (Test-Path -LiteralPath $Path)) { return $true }

                try {
                    Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop
                }
                catch {
                    # Un fichier peut rester verrouillé quelques millisecondes
                    # après la fin de 7-Zip ou de Robocopy.
                }

                if (-not (Test-Path -LiteralPath $Path)) { return $true }
                Start-Sleep -Milliseconds 300
            }

            return (-not (Test-Path -LiteralPath $Path))
        }

        $baseState = @{
            Machine               = $Job.Machine
            FQDN                  = $Job.FQDN
            TargetHost            = $Job.TargetHost
            DomainID              = $Job.DomainID
            SourcePath            = $Job.SourcePath
            LastSeenUtc           = (Get-Date).ToUniversalTime().ToString("o")
            LastServerVersion     = $Job.SourceVersion
            LastServerZipName     = $Job.SourceZipName
            LastServerZipWriteUtc = $Job.SourceZipWriteUtc
            LastSeenServerUtc     = (Get-Date).ToUniversalTime().ToString("o")
        }

        $isOnline = $false
        $tcpClient = New-Object System.Net.Sockets.TcpClient
        try {
            $asyncResult = $tcpClient.BeginConnect($Job.TargetHost, 445, $null, $null)
            $isOnline = $asyncResult.AsyncWaitHandle.WaitOne(1500, $true)
            if ($isOnline) { $tcpClient.EndConnect($asyncResult) }
        } catch {
            $isOnline = $false
        } finally {
            $tcpClient.Close()
            $tcpClient.Dispose()
        }

        if (-not $isOnline) {
            Write-State -StateData ($baseState + @{
                LastResult   = "Offline"
                LastMessage  = "Machine injoignable (port 445 fermé ou PC éteint)"
                LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            return @{
                PC     = $Job.FQDN
                Status = "Warning"
                Msg    = "Machine injoignable (Port 445 fermé ou PC éteint)"
            }
        }

        Publish-JobProgress -Stage "EXTRACTION" -Message "poste joignable, extraction de $($Job.SourceZipName) ($(Format-ByteSize -Bytes ([int64]$Job.SourceZipSize)))..."

        $Guid        = [Guid]::NewGuid()
        $MyTempDir   = Join-Path $TempRoot "Ext_$Guid"
        $My7zWorkDir = Join-Path $TempRoot "7zWork_$Guid"
        $DestShare   = "\\$($Job.TargetHost)\procedureDegradee$"
        $7zStdOut    = Join-Path $env:TEMP "7zip_$($Job.Machine)_$($Guid.ToString('N')).out.log"
        $7zStdErr    = Join-Path $env:TEMP "7zip_$($Job.Machine)_$($Guid.ToString('N')).err.log"
        $RoboLog     = $null

        try {
            $ExtractStartedAt = Get-Date
            New-Item -Path $MyTempDir -ItemType Directory -Force -ErrorAction Stop | Out-Null
            New-Item -Path $My7zWorkDir -ItemType Directory -Force -ErrorAction Stop | Out-Null

            # Chaque job a son propre dossier 7-Zip : pas de conflit entre les extractions parallèles.
            $SevenZipStartInfo = @{
                FilePath               = $7zExe
                # Mode silencieux : aucun nom de fichier extrait dans les logs.
                # Les erreurs restent envoyées sur stderr pour le diagnostic.
                ArgumentList           = "x `"$($Job.SourceZip)`" -o`"$MyTempDir`" -w`"$My7zWorkDir`" -y -bb0 -bso0 -bsp0 -bse1"
                NoNewWindow            = $true
                PassThru               = $true
                Wait                   = $true
                RedirectStandardOutput = $7zStdOut
                RedirectStandardError  = $7zStdErr
            }
            $7zProc = Start-Process @SevenZipStartInfo
            $7zProc.Refresh()

            # On limite le diagnostic aux 20 dernières lignes pour ne jamais
            # injecter la liste complète du contenu du ZIP dans le journal.
            $7zOutput = @()
            if (Test-Path $7zStdErr) {
                $7zOutput += Get-Content -Path $7zStdErr -Tail 20 -ErrorAction SilentlyContinue
            }
            if ($7zOutput.Count -eq 0 -and (Test-Path $7zStdOut)) {
                $7zOutput += Get-Content -Path $7zStdOut -Tail 20 -ErrorAction SilentlyContinue
            }
            $7zDetail = ($7zOutput -join [Environment]::NewLine).Trim()
            Remove-Item $7zStdOut, $7zStdErr -Force -ErrorAction SilentlyContinue

            if ($7zProc.ExitCode -ge 2) {
                Write-State -StateData ($baseState + @{
                    LastResult   = "ExtractError"
                    LastMessage  = "Échec extraction 7-Zip (code $($7zProc.ExitCode))"
                    LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Error"
                    Msg    = "Échec extraction 7-Zip (code $($7zProc.ExitCode))"
                    Detail = "ZIP source : $($Job.SourceZip)" + $(if ($7zDetail) { [Environment]::NewLine + $7zDetail } else { "" })
                }
            }

            $ExtractedFiles = @(Get-ChildItem -Path $MyTempDir -Recurse -File -ErrorAction SilentlyContinue)
            if ($ExtractedFiles.Count -eq 0) {
                Write-State -StateData ($baseState + @{
                    LastResult   = "EmptyExtract"
                    LastMessage  = "Dossier extrait vide après 7-Zip"
                    LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Error"
                    Msg    = "Dossier extrait vide après 7-Zip"
                    Detail = "ZIP source : $($Job.SourceZip)"
                }
            }

            $ExtractedFileCount = $ExtractedFiles.Count
            $ExtractedBytes = [int64](($ExtractedFiles | Measure-Object -Property Length -Sum).Sum)
            $ExtractDurationSec = [math]::Round(((Get-Date) - $ExtractStartedAt).TotalSeconds, 1)
            Publish-JobProgress -Stage "CONNEXION SMB" -Message "extraction terminée en ${ExtractDurationSec}s : $ExtractedFileCount fichier(s), $(Format-ByteSize -Bytes $ExtractedBytes). Connexion au partage cible..."

            $pcPassword = Get-CredentialFromFile -CredFilePath $Job.CredFile

            $netUseStdOut = Join-Path $env:TEMP "netuse_$($Job.Machine)_$([Guid]::NewGuid().ToString('N')).out.log"
            $netUseStdErr = Join-Path $env:TEMP "netuse_$($Job.Machine)_$([Guid]::NewGuid().ToString('N')).err.log"

            $netUseArgs = @(
                'use'
                $DestShare
                "/user:$($Job.UserLogin)"
                $pcPassword
                '/persistent:no'
            )

            $netProc = Start-Process -FilePath 'net.exe' `
                -ArgumentList $netUseArgs `
                -PassThru `
                -WindowStyle Hidden `
                -RedirectStandardOutput $netUseStdOut `
                -RedirectStandardError $netUseStdErr

            $netFinished = $netProc.WaitForExit(30000)
            $pcPassword = $null

            if (-not $netFinished) {
                try { $netProc.Kill() } catch {}

                $netDetail = @()
                if (Test-Path $netUseStdOut) { $netDetail += Get-Content -Path $netUseStdOut -ErrorAction SilentlyContinue }
                if (Test-Path $netUseStdErr) { $netDetail += Get-Content -Path $netUseStdErr -ErrorAction SilentlyContinue }

                Remove-Item $netUseStdOut, $netUseStdErr -Force -ErrorAction SilentlyContinue

                Write-State -StateData ($baseState + @{
                    LastResult   = "SMBConnectTimeout"
                    LastMessage  = "Timeout connexion SMB (>30s)"
                    LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Warning"
                    Msg    = "Timeout connexion SMB (>30s)"
                    Detail = ($netDetail -join [Environment]::NewLine)
                }
            }

            # Important : on force la finalisation complète des flux et on refresh l'objet process
            $netProc.WaitForExit()
            $netProc.Refresh()

            $netExitCode = $netProc.ExitCode
            $netStdOut   = if (Test-Path $netUseStdOut) { Get-Content -Path $netUseStdOut -ErrorAction SilentlyContinue | Out-String } else { "" }
            $netStdErr   = if (Test-Path $netUseStdErr) { Get-Content -Path $netUseStdErr -ErrorAction SilentlyContinue | Out-String } else { "" }
            $netResult   = ($netStdOut + $netStdErr).Trim()

            Remove-Item $netUseStdOut, $netUseStdErr -Force -ErrorAction SilentlyContinue

            # Vérification réelle du partage : c'est ça qui doit faire foi
            $shareAccessible = $false
            try {
                $shareAccessible = Test-Path -LiteralPath $DestShare -ErrorAction Stop
            }
            catch {
                $shareAccessible = $false
            }

            if (-not $shareAccessible) {
                Write-State -StateData ($baseState + @{
                    LastResult   = "SMBConnectError"
                    LastMessage  = "Connexion SMB établie mais partage inaccessible"
                    LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Error"
                    Msg    = "Partage SMB inaccessible"
                    Detail = "ExitCode=$netExitCode ; Sortie=$netResult"
                }
            }

            Publish-JobProgress -Stage "COPIE" -Message "partage cible accessible, copie Robocopy en cours..."

            # Si le partage est accessible, on continue, même si ExitCode est étrange
            if ($netExitCode -ne 0) {
                Write-State -StateData ($baseState + @{
                    LastPcReachableUtc = (Get-Date).ToUniversalTime().ToString("o")
                    LastResult         = "SMBConnectWeirdExitCode"
                    LastMessage        = "Connexion SMB OK malgré ExitCode non nul ($netExitCode)"
                    LastErrorUtc       = $null
                })
            }

            $RoboLog  = Join-Path $env:TEMP "robocopy_$($Job.Machine)_$(Get-Date -Format 'yyyyMMdd_HHmmss').log"
            # Chaque Robocopy utilise 4 threads ; la concurrence globale est définie par $MaxThreads.
            $RoboArgs = "`"$MyTempDir`" `"$DestShare`" /MIR /MT:4 /R:2 /W:1 /NFL /NDL /NJH /NJS /LOG:`"$RoboLog`""
            $CopyStartedAt = Get-Date
            $Copy = Start-Process robocopy.exe -ArgumentList $RoboArgs -NoNewWindow -Wait -PassThru

            net use "$DestShare" /delete /y 2>&1 | Out-Null

            if ($Copy.ExitCode -lt 8) {
                $CopyDurationSec = [math]::Round(((Get-Date) - $CopyStartedAt).TotalSeconds, 1)
                $CleanupAnnounced = $true
                Publish-JobProgress -Stage "NETTOYAGE" -Message "copie terminée en ${CopyDurationSec}s (code $($Copy.ExitCode)), nettoyage de $(Format-ByteSize -Bytes $ExtractedBytes)..."
                Remove-Item -Path $RoboLog -Force -ErrorAction SilentlyContinue

                Write-State -StateData ($baseState + @{
                    LastDeployVersion  = $Job.SourceVersion
                    LastDeployUtc      = (Get-Date).ToUniversalTime().ToString("o")
                    LastPcReachableUtc = (Get-Date).ToUniversalTime().ToString("o")
                    LastResult         = "Success"
                    LastMessage        = "Synchronisation OK"
                    LastErrorUtc       = $null
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Success"
                }
            }
            else {
                $RoboDetail = if (Test-Path $RoboLog) {
                    Get-Content $RoboLog -Tail 10 | Out-String
                } else {
                    "Log Robocopy indisponible"
                }
                Remove-Item -Path $RoboLog -Force -ErrorAction SilentlyContinue

                Write-State -StateData ($baseState + @{
                    LastPcReachableUtc = (Get-Date).ToUniversalTime().ToString("o")
                    LastResult         = "RobocopyError"
                    LastMessage        = "Erreur Robocopy code $($Copy.ExitCode)"
                    LastErrorUtc       = (Get-Date).ToUniversalTime().ToString("o")
                })

                return @{
                    PC     = $Job.FQDN
                    Status = "Error"
                    Msg    = "Erreur Robocopy code $($Copy.ExitCode)"
                    Detail = $RoboDetail
                }
            }
        }
        catch {
            Write-State -StateData ($baseState + @{
                LastResult   = "SystemException"
                LastMessage  = "Exception système"
                LastErrorUtc = (Get-Date).ToUniversalTime().ToString("o")
            })

            return @{
                PC     = $Job.FQDN
                Status = "Error"
                Msg    = "Exception système"
                Detail = $_.Exception.Message
            }
        }
        finally {
            $CleanupStartedAt = Get-Date
            if (-not $CleanupAnnounced) {
                Publish-JobProgress -Stage "NETTOYAGE" -Message "nettoyage des fichiers temporaires..."
            }
            net use "$DestShare" /delete /y 2>&1 | Out-Null
            Remove-Item $7zStdOut, $7zStdErr -Force -ErrorAction SilentlyContinue
            if ($RoboLog) {
                Remove-Item -Path $RoboLog -Force -ErrorAction SilentlyContinue
            }

            # Le résultat du job n’est rendu qu’après ce nettoyage : le poste
            # suivant ne prend donc le slot qu’une fois l’espace disque libéré.
            $ExtractCleanupOk = Remove-TempDirectoryWithRetry -Path $MyTempDir
            $WorkCleanupOk    = Remove-TempDirectoryWithRetry -Path $My7zWorkDir
            $CleanupDurationSec = [math]::Round(((Get-Date) - $CleanupStartedAt).TotalSeconds, 1)

            if (-not ($ExtractCleanupOk -and $WorkCleanupOk)) {
                Publish-JobProgress -Stage "TERMINÉ" -Message "nettoyage incomplet après ${CleanupDurationSec}s ; une nouvelle tentative sera faite en fin de cycle." -Type "WARNING"
            }
        }
    }

    $RunspacePool = [runspacefactory]::CreateRunspacePool(1, $MaxThreads)
    $RunspacePool.Open()

    function Flush-JobInformation {
        param([hashtable]$JobRecord)

        try {
            $informationStream = $JobRecord.Pipe.Streams.Information

            while ($JobRecord.InfoIndex -lt $informationStream.Count) {
                $record = $informationStream[$JobRecord.InfoIndex]
                $JobRecord.InfoIndex++
                $data = $record.MessageData

                if ($data -and $data.Kind -eq "ProcDegProgress") {
                    $JobRecord.Stage = [string]$data.Stage
                    $logType = if ($data.Type -in @("INFO", "WARNING", "ERROR", "SUCCESS", "DEBUG")) {
                        [string]$data.Type
                    } else { "DEBUG" }

                    Write-Log "$($data.PC) : $($data.Message)" $logType
                }
            }
        }
        catch {
            # La collecte des informations ne doit jamais interrompre une synchro.
        }
    }

    # Le timeout global couvre désormais aussi le scan initial des partages.
    $GlobalStart = $CycleStart
    $PendingQueue = New-Object System.Collections.Queue
    foreach ($item in $WorkQueue) {
        $PendingQueue.Enqueue($item)
    }

    $Jobs = New-Object System.Collections.ArrayList
    $StopStartingNewJobs = $false
    $TotalWorkItems      = $WorkQueue.Count
    $StartedCount        = 0
    $CompletedCount      = 0
    $SuccessCount        = 0
    $WarningCount        = 0
    $ErrorCount          = 0
    $AbortedCount        = 0
    $LastSummaryAt       = Get-Date

    while ($PendingQueue.Count -gt 0 -or @($Jobs | Where-Object { -not $_.Handled }).Count -gt 0) {
        $ElapsedSec   = ((Get-Date) - $GlobalStart).TotalSeconds
        $RemainingSec = $GlobalTimeoutSec - $ElapsedSec

        if (-not $StopStartingNewJobs -and $RemainingSec -le 15){
            $StopStartingNewJobs = $true
            Write-Log "Moins de 15 secondes restantes : plus aucun nouveau poste ne sera lancé dans ce cycle." "WARNING"
        }

        if ($ElapsedSec -gt $GlobalTimeoutSec) {
            Write-Log "TIMEOUT GLOBAL atteint ($GlobalTimeoutSec s)." "WARNING"

            foreach ($Job in ($Jobs | Where-Object { -not $_.Handled })) {
                $Job.Handled = $true
                $AbortedCount++
                try { $Job.Pipe.Stop() } catch {}
                $Job.Pipe.Dispose()
            }
            break
        }

        # @(...).Count est indispensable ici : lorsqu'il ne reste qu'une seule
        # Hashtable, PowerShell retournerait sinon le nombre de ses champs (8)
        # au lieu de compter 1 job, ce qui bloquerait le remplissage des slots.
        while (-not $StopStartingNewJobs -and $PendingQueue.Count -gt 0 -and (@($Jobs | Where-Object { -not $_.Handled }).Count -lt $MaxThreads)) {
            $WorkItem = $PendingQueue.Dequeue()
            $StartedCount++

            $PS = [powershell]::Create().AddScript($ScriptBlock).AddArgument($WorkItem).AddArgument($TempExtractRoot).AddArgument($7zPath)
            $PS.RunspacePool = $RunspacePool

            $null = $Jobs.Add(@{
                Pipe      = $PS
                Result    = $PS.BeginInvoke()
                PC        = $WorkItem.FQDN
                Handled   = $false
                StartTime = Get-Date
                InfoIndex = 0
                Stage     = "DÉMARRAGE"
                Sequence  = $StartedCount
            })

            $ActiveCount = @($Jobs | Where-Object { -not $_.Handled }).Count
            Write-Log "LANCÉ [$StartedCount/$TotalWorkItems] : $($WorkItem.FQDN) (actifs $ActiveCount/$MaxThreads, attente $($PendingQueue.Count))." "INFO"
        }

        # Remonte en temps réel les changements d’étape des runspaces.
        foreach ($RunningJob in ($Jobs | Where-Object { -not $_.Handled })) {
            Flush-JobInformation -JobRecord $RunningJob
        }

        # Une synthèse toutes les 60 secondes permet de suivre les gros cycles
        # sans écrire une ligne en permanence.
        if (((Get-Date) - $LastSummaryAt).TotalSeconds -ge 60) {
            $ActiveJobs = @($Jobs | Where-Object { -not $_.Handled -and -not $_.Result.IsCompleted })
            $StageSummary = @($ActiveJobs |
                Group-Object -Property Stage |
                Sort-Object -Property Name |
                ForEach-Object { "$($_.Name)=$($_.Count)" }) -join ", "

            if ([string]::IsNullOrWhiteSpace($StageSummary)) { $StageSummary = "aucun" }

            $StorageNow = Get-TempStorageStatus
            $StorageText = if ($StorageNow) { " | disque=$($StorageNow.FreeGB) Go libres" } else { "" }

            Write-Log "ÉTAT : $CompletedCount/$TotalWorkItems terminés, $($ActiveJobs.Count) actif(s), $($PendingQueue.Count) en attente | $($StageSummary)$($StorageText)." "INFO"
            $LastSummaryAt = Get-Date
        }

        foreach ($Job in ($Jobs | Where-Object { $_.Result.IsCompleted -and -not $_.Handled })) {
            $Job.Handled = $true
            try {
                $Res = $Job.Pipe.EndInvoke($Job.Result)
            }
            catch {
                $Res = [pscustomobject]@{
                    PC     = $Job.PC
                    Status = "Error"
                    Msg    = "Le traitement parallèle s’est interrompu"
                    Detail = $_.Exception.Message
                }
            }
            Flush-JobInformation -JobRecord $Job
            $CompletedCount++
            $JobDurationSec = [math]::Round(((Get-Date) - $Job.StartTime).TotalSeconds, 1)

            if ($Res.Status -eq "Success") {
                $SuccessCount++
                Write-Log "TERMINÉ [$CompletedCount/$TotalWorkItems] : $($Res.PC) synchronisé en ${JobDurationSec}s." "SUCCESS"
            }
            elseif ($Res.Status -eq "Warning") {
                $WarningCount++
                Write-Log "TERMINÉ [$CompletedCount/$TotalWorkItems] : $($Res.PC) ignoré en ${JobDurationSec}s - $($Res.Msg)" "WARNING"
            }
            else {
                $ErrorCount++
                Write-Log "TERMINÉ [$CompletedCount/$TotalWorkItems] : $($Res.PC) en échec après ${JobDurationSec}s - $($Res.Msg)" "ERROR"
                if ($Res.Detail) {
                    Write-Log "    Détail : $($Res.Detail)" "ERROR"
                }
            }

            $Job.Pipe.Dispose()
        }

        Start-Sleep -Milliseconds 100
    }

    $RunspacePool.Close()
    $RunspacePool.Dispose()

    # Filet de sécurité : supprime les éventuels dossiers ayant résisté au
    # nettoyage individuel (par exemple après l’arrêt forcé d’un job).
    $RemainingTempDirs = @(Get-ChildItem -Path $TempExtractRoot -Directory -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like "Ext_*" -or $_.Name -like "7zWork_*" })

    $CleanupFailures = New-Object System.Collections.ArrayList
    foreach ($tempDir in $RemainingTempDirs) {
        for ($attempt = 1; $attempt -le 5; $attempt++) {
            if (-not (Test-Path -LiteralPath $tempDir.FullName)) { break }
            Remove-Item -LiteralPath $tempDir.FullName -Recurse -Force -ErrorAction SilentlyContinue
            if (Test-Path -LiteralPath $tempDir.FullName) {
                Start-Sleep -Milliseconds 300
            }
        }

        if (Test-Path -LiteralPath $tempDir.FullName) {
            $null = $CleanupFailures.Add($tempDir.FullName)
        }
    }

    if ($CleanupFailures.Count -gt 0) {
        Write-Log "$($CleanupFailures.Count) dossier(s) temporaire(s) n’ont pas pu être supprimés et seront retentés au prochain cycle." "WARNING"
    }

    foreach ($path in $MappedSources.Keys) {
        if ($MappedSources[$path]) {
            net use "$path" /delete /y 2>&1 | Out-Null
            Write-Log "Partage source démonté : $path" "DEBUG"
        }
    }

    $CycleDurationSec = [math]::Round(((Get-Date) - $CycleStart).TotalSeconds, 1)
    $FinalStorage = Get-TempStorageStatus
    $FinalStorageText = if ($FinalStorage) { " Espace libre final : $($FinalStorage.FreeGB) Go." } else { "" }
    Write-Log "BILAN : $CompletedCount/$TotalWorkItems traité(s) en ${CycleDurationSec}s — $SuccessCount succès, $WarningCount ignoré(s), $ErrorCount erreur(s), $AbortedCount interrompu(s), $($PendingQueue.Count) restant(s).$($FinalStorageText)" "INFO"
    Write-Log "--- FIN DU CYCLE ---" "INFO"
}
finally {
    Release-RunLock
}

