# Priorité de passage dans la file. Beaucoup de lots arrivent aux mêmes heures
# (heures impaires notamment) : sans tri, la file suit l'ordre du JSON et les
# derniers postes attendent systématiquement plusieurs cycles.
#   - un profil exprimé en durée ("30MIN") est traité comme une urgence ;
#   - ensuite, les profils ayant le moins de lots par jour passent en premier,
#     car un créneau manqué y représente une perte plus importante ;
#   - un profil inconnu passe en dernier.
function Get-ProfilePriority {
    param(
        [object]$Horaires,
        [string]$ProfileName
    )

    $unknown = [pscustomobject]@{ IsUrgent = $false; LotsPerDay = 999 }

    if ([string]::IsNullOrWhiteSpace($ProfileName) -or -not $Horaires) { return $unknown }
    if (-not ($Horaires.PSObject.Properties.Name -contains $ProfileName)) { return $unknown }

    $value = $Horaires.$ProfileName

    if ($value -is [string]) {
        return [pscustomobject]@{ IsUrgent = $true; LotsPerDay = 0 }
    }

    $hours = @($value | ForEach-Object { $_ -as [int] } | Where-Object { $null -ne $_ -and $_ -ge 0 -and $_ -le 23 } | Sort-Object -Unique)
    if ($hours.Count -eq 0) { return $unknown }

    return [pscustomobject]@{ IsUrgent = $false; LotsPerDay = $hours.Count }
}

