        PC        = $WorkItem.FQDN
        Handled   = $false
        StartTime = Get-Date
        InfoIndex = 0
        Stage     = "DÉMARRAGE"
        Sequence  = $StartedCount
    })

    $ActiveCount = @($Jobs | Where-Object { -not $_.Handled }).Count
