        Group-Object -Property Stage |
        Sort-Object -Property Name |
        ForEach-Object { "$($_.Name)=$($_.Count)" }) -join ", "

    if ([string]::IsNullOrWhiteSpace($StageSummary)) { $StageSummary = "aucun" }

