    $zipWriteUtc = [DateTime]::Parse(
        [string]$Job.SourceZipWriteUtc,
        [Globalization.CultureInfo]::InvariantCulture,
        [Globalization.DateTimeStyles]::RoundtripKind
    ).ToUniversalTime()
    $delay = [math]::Round(($DeployUtc - $zipWriteUtc).TotalSeconds)
    # Un délai négatif signale un décalage d'horloge avec le serveur source.
    if ($delay -ge 0) { $DeployDelaySec = [int64]$delay }
} catch {}

