    LastDeployUtc      = $DeployUtc.ToString("o")
    LastDeployDelaySec = $DeployDelaySec
    LastPcReachableUtc = $DeployUtc.ToString("o")
    LastResult         = "Success"
    LastMessage        = "Synchronisation OK"
    LastErrorUtc       = $null
})

return @{
